apprentice_compile(struct magic_set *ms, struct magic_map *map, const char *fn)
{
        static const size_t nm = sizeof(*map->nmagic) * MAGIC_SETS;
        static const size_t m = sizeof(**map->magic);
        int fd = -1;
        size_t len;
        char *dbname;
        int rv = -1;
        uint32_t i;
        union {
                struct magic m;
                uint32_t h[2 + MAGIC_SETS];
        } hdr;

        dbname = mkdbname(ms, fn, 1);

        if (dbname == NULL)
                goto out;

        if ((fd = open(dbname, O_WRONLY|O_CREAT|O_TRUNC|O_BINARY, 0644)) == -1)
        {
                file_error(ms, errno, "cannot open `%s'", dbname);
                goto out;
        }
        memset(&hdr, 0, sizeof(hdr));
        hdr.h[0] = MAGICNO;
        hdr.h[1] = VERSIONNO;
        memcpy(hdr.h + 2, map->nmagic, nm);

        if (write(fd, &hdr, sizeof(hdr)) != CAST(ssize_t, sizeof(hdr))) {
                file_error(ms, errno, "error writing `%s'", dbname);
                goto out2;
        }

        for (i = 0; i < MAGIC_SETS; i++) {
                len = m * map->nmagic[i];
                if (write(fd, map->magic[i], len) != CAST(ssize_t, len)) {
                        file_error(ms, errno, "error writing `%s'", dbname);
                        goto out2;
                }
        }

        rv = 0;
out2:
        if (fd != -1)
                (void)close(fd);
out:
        apprentice_unmap(map);
        free(dbname);
        return rv;
}

private const char ext[] = ".mgc";
/*
 * make a dbname
 */
private char *
mkdbname(struct magic_set *ms, const char *fn, int strip)
{
        const char *p, *q;
        char *buf;

        if (strip) {
                if ((p = strrchr(fn, '/')) != NULL)
                        fn = ++p;
        }

        for (q = fn; *q; q++)
                continue;
        /* Look for .mgc */
        for (p = ext + sizeof(ext) - 1; p >= ext && q >= fn; p--, q--)
                if (*p != *q)
                        break;

        /* Did not find .mgc, restore q */
        if (p >= ext)
                while (*q)
                        q++;

        q++;
        /* Compatibility with old code that looked in .mime */
        if (ms->flags & MAGIC_MIME) {
                if (asprintf(&buf, "%.*s.mime%s", CAST(int, q - fn), fn, ext)
                    < 0)
                        return NULL;
                if (access(buf, R_OK) != -1) {
                        ms->flags &= MAGIC_MIME_TYPE;
                        return buf;
                }
                free(buf);
        }
        if (asprintf(&buf, "%.*s%s", CAST(int, q - fn), fn, ext) < 0)
                return NULL;

        /* Compatibility with old code that looked in .mime */
        if (strstr(fn, ".mime") != NULL)
                ms->flags &= MAGIC_MIME_TYPE;
        return buf;
}

/*
 * Byteswap an mmap'ed file if needed
 */
private void
byteswap(struct magic *magic, uint32_t nmagic)
{
        uint32_t i;
        for (i = 0; i < nmagic; i++)
                bs1(&magic[i]);
}

#if !defined(HAVE_BYTESWAP_H) && !defined(HAVE_SYS_BSWAP_H)
/*
 * swap a short
 */
private uint16_t
swap2(uint16_t sv)
{
        uint16_t rv;
        uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
        uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
        d[0] = s[1];
        d[1] = s[0];
        return rv;
}

/*
 * swap an int
 */
private uint32_t
swap4(uint32_t sv)
{
        uint32_t rv;
        uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
        uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
        d[0] = s[3];
        d[1] = s[2];
        d[2] = s[1];
        d[3] = s[0];
        return rv;
}

/*
 * swap a quad
 */
private uint64_t
swap8(uint64_t sv)
{
        uint64_t rv;
        uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
        uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
# if 0
        d[0] = s[3];
        d[1] = s[2];
        d[2] = s[1];
        d[3] = s[0];
        d[4] = s[7];
        d[5] = s[6];
        d[6] = s[5];
        d[7] = s[4];
# else
        d[0] = s[7];
        d[1] = s[6];
        d[2] = s[5];
        d[3] = s[4];
        d[4] = s[3];
        d[5] = s[2];
        d[6] = s[1];
        d[7] = s[0];
# endif
        return rv;
}
#endif

protected uintmax_t
file_varint2uintmax_t(const unsigned char *us, int t, size_t *l)
{
        uintmax_t x = 0;
        const unsigned char *c;
        if (t == FILE_LEVARINT) {
                for (c = us; *c; c++) {
                        if ((*c & 0x80) == 0)
                                break;
                }
                if (l)
                        *l = c - us + 1;
                for (; c >= us; c--) {
                        x |= *c & 0x7f;
                        x <<= 7;
                }
        } else {
                for (c = us; *c; c++) {
                        x |= *c & 0x7f;
                        if ((*c & 0x80) == 0)
                                break;
                        x <<= 7;
                }
                if (l)
                        *l = c - us + 1;
        }
        return x;
}


/*
 * byteswap a single magic entry
 */
private void
bs1(struct magic *m)
{
        m->cont_level = swap2(m->cont_level);
        m->offset = swap4(CAST(uint32_t, m->offset));
        m->in_offset = swap4(CAST(uint32_t, m->in_offset));
        m->lineno = swap4(CAST(uint32_t, m->lineno));
        if (IS_STRING(m->type)) {
                m->str_range = swap4(m->str_range);
                m->str_flags = swap4(m->str_flags);
        }
        else {
                m->value.q = swap8(m->value.q);
                m->num_mask = swap8(m->num_mask);
        }
}

protected size_t
file_pstring_length_size(struct magic_set *ms, const struct magic *m)
{
        switch (m->str_flags & PSTRING_LEN) {
        case PSTRING_1_LE:
                return 1;
        case PSTRING_2_LE:
        case PSTRING_2_BE:
                return 2;
        case PSTRING_4_LE:
        case PSTRING_4_BE:
                return 4;
        default:
                file_error(ms, 0, "corrupt magic file "
                    "(bad pascal string length %d)",
                    m->str_flags & PSTRING_LEN);
                return FILE_BADSIZE;
        }
}
protected size_t
file_pstring_get_length(struct magic_set *ms, const struct magic *m,
    const char *ss)
{
        size_t len = 0;
        const unsigned char *s = RCAST(const unsigned char *, ss);
        unsigned int s3, s2, s1, s0;

        switch (m->str_flags & PSTRING_LEN) {
        case PSTRING_1_LE:
                len = *s;
                break;
        case PSTRING_2_LE:
                s0 = s[0];
                s1 = s[1];
                len = (s1 << 8) | s0;
                break;
        case PSTRING_2_BE:
                s0 = s[0];
                s1 = s[1];
                len = (s0 << 8) | s1;
                break;
        case PSTRING_4_LE:
                s0 = s[0];
                s1 = s[1];
                s2 = s[2];
                s3 = s[3];
                len = (s3 << 24) | (s2 << 16) | (s1 << 8) | s0;
                break;
        case PSTRING_4_BE:
                s0 = s[0];
                s1 = s[1];
                s2 = s[2];
                s3 = s[3];
                len = (s0 << 24) | (s1 << 16) | (s2 << 8) | s3;
                break;
        default:
                file_error(ms, 0, "corrupt magic file "
                    "(bad pascal string length %d)",
                    m->str_flags & PSTRING_LEN);
                return FILE_BADSIZE;
        }

        if (m->str_flags & PSTRING_LENGTH_INCLUDES_ITSELF) {
                size_t l = file_pstring_length_size(ms, m);
                if (l == FILE_BADSIZE)
                        return l;
                len -= l;
        }

        return len;
}

protected int
file_magicfind(struct magic_set *ms, const char *name, struct mlist *v)
{
        uint32_t i, j;
        struct mlist *mlist, *ml;

        mlist = ms->mlist[1];

        for (ml = mlist->next; ml != mlist; ml = ml->next) {
                struct magic *ma = ml->magic;
                for (i = 0; i < ml->nmagic; i++) {
                        if (ma[i].type != FILE_NAME)
                                continue;
                        if (strcmp(ma[i].value.s, name) == 0) {
                                v->magic = &ma[i];
                                v->magic_rxcomp = &(ml->magic_rxcomp[i]);
                                for (j = i + 1; j < ml->nmagic; j++)
                                    if (ma[j].cont_level == 0)
                                            break;
                                v->nmagic = j - i;
                                return 0;
                        }
                }
        }
        return -1;
}
